input.command:
REPO_OWNER=$(gh repo view --json owner --jq '.owner.login') && REPO_NAME=$(gh repo view --json name --jq '.name') && gh api graphql -f query="
{
  repository(owner: \"$REPO_OWNER\", name: \"$REPO_NAME\") {
    pullRequest(number: 261) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          comments(first: 10) {
            nodes {
              id
              databaseId
              author { login }
              body
              path
              line
              createdAt
            }
          }
        }
      }
    }
  }
}"

gh api graphql -f query='
mutation {
  t1: resolveReviewThread(input: {threadId: "PRRT_kwDOQ6DXvM5x7pI0"}) {
    thread { isResolved }
  }
  t2: resolveReviewThread(input: {threadId: "PRRT_kwDOQ6DXvM5x7pI3"}) {
    thread { isResolved }
  }
  t3: resolveReviewThread(input: {threadId: "PRRT_kwDOQ6DXvM5x7pI6"}) {
    thread { isResolved }
  }
}'

REPO_OWNER=$(gh repo view --json owner --jq '.owner.login') && REPO_NAME=$(gh repo view --json name --jq '.name') && gh api graphql -f query="
{
  repository(owner: \"$REPO_OWNER\", name: \"$REPO_NAME\") {
    pullRequest(number: 261) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          comments(first: 10) {
            nodes {
              id
              databaseId
              author { login }
              body
              path
              line
              createdAt
            }
          }
        }
      }
    }
  }
}" | jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved == false)]'
